    // Strategy: Minimize the post_residual (Best Fit) while applying a penalty 
    // for creating "sliver" spaces that are likely too small for future items.

    let mut score = post_residual as f64;

    // 1. Penalty for creating small, unusable gaps (1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead logic: If the next item fits into the post_residual, 
    // reward this bin to keep the bin chain tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global state: If we are nearing the end of the stream, 
    // prioritize packing tighter (lowering score) to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    // 4. New Bin Logic: If bin_residual == bin_capacity, this is a candidate for a new bin.
    // We only want to open a new bin if the mean residual of current bins is high,
    // or if the current item is very large and doesn't fit well elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 10.0; // Force opening if no other options
        } else {
            // Otherwise, make opening a new bin expensive to discourage fragmentation
            score = 100.0 + (mean_residual * 0.5);
        }
    } else {
        // 5. If this bin is the last chance (fitting_bins_count == 1), 
        // aggressively lower the score to ensure we don't open a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

