    // 2. Adaptive Lookahead Coupling:
    // If next_item_size is known, reward bins that can accommodate it cleanly,
    // creating a "lookahead-gap" which is smaller and more likely to be filled by subsequent items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // Heavily reward bins that leave a very small residual after the next item (synergy)
            score -= (next_post as f64 * 1.2) + 30.0;
        } else {
            // Penalize bins that strand the next item if we have plenty of open bins
            score += 25.0 + (open_bins_count as f64 * 0.5);
        }
    }

    // 3. Harmonic Alignment:
    // Reward residuals that are multiples of 20 or 25, as these align with common item distributions.
    if post_residual % 20 == 0 {
        score -= 15.0;
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    }

    // 4. New Bin Thresholding:
    // Aggressively discourage opening a new bin unless existing bins are extremely fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 95.0; 
        } else {
            score -= 50.0;
        }
