        let progress = (step_index as f64 / total_items as f64).powf(0.5);
        score -= progress * 20.0;

        // 6. Mean Residual Balancing:
        // Penalize bins that deviate significantly from the mean to encourage uniformity.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.35;

        // 7. Density Bonus: If this is the only bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 20.0;
