    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual ranges that are too small to be useful
    // (e.g., < 10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open bins pressure: If this is an existing bin, penalize it if we have too many open bins.
    // This encourages filling existing bins rather than spreading items thin.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    // 3. Lookahead integration: If next_item_size exists, penalize post_residual if it's 
    // too small to accommodate the next item (which is likely > 10).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. New bin penalty: If this is a new bin (residual == capacity), apply a baseline 
    // cost that is only worth it if all existing bins result in very poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 5. Fitting bin scarcity: If this is the only bin that can fit the item, 
    // significantly lower its score to ensure we don't accidentally open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Efficiency bias: Reward bins that are closer to the mean residual of the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

