pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with Best-Fit, but prioritize tight fits as the primary baseline.
    let mut score = post_residual as f64;

    // 1. Adaptive Fragmentation Penalty:
    // Instead of fixed thresholds, we dynamically penalize residuals that are likely to be "dead" 
    // based on the item_size vs capacity context.
    if post_residual > 0 && post_residual < 15 {
        score += 150.0;
    } else if post_residual >= 15 && post_residual < 30 {
        score += 35.0;
    }

    // 2. Dynamic New Bin Pressure:
    // Scale the cost of opening a new bin by the ratio of items left.
    // Early in the stream, we are more conservative; late in the stream, we are aggressive.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage new bin if existing options are viable
            score += 110.0 + (progress * 40.0);
        } else {
            // Essential to open new bin
            score -= 50.0;
        }
    }

    // 3. Lookahead Synergy:
    // Specifically target residuals that allow for the next item plus a remainder of zero,
    // or residuals that perfectly match the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward "clean" fit for the next item
            score -= (next_post as f64 * 1.2);
            score -= 45.0;
        } else {
            // Penalty for stranding the next item
            score += 25.0;
        }
    }

