    // Force convergence toward the mean to avoid extreme fragmentation.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.4;

    // 5. Fitting Constraint:
    // If this is the only bin that can house the item, prioritize it heavily
    // to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Harmonic Preference:
    // Prefer bin residual levels that are multiples of 20 (common in many distributions).
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize smaller post_residuals (Best Fit)
    // We penalize the new bin creation quadratically based on progress to discourage it late-stream
    let mut score = post_res.powf(1.5);

    if is_new_bin {
        // Penalty for opening a new bin is weighted by progress and current fragmentation
        // As progress increases, we become more reluctant to open new bins
        score = 85.0 + (progress * 40.0) + (mean_residual * 0.5);
    } else {
        // If this is the only bin that fits, we reward it to avoid opening a new one
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Lookahead heuristic: if the next item fits into the current post_residual,
        // reduce the score to prefer this bin (clustering)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64 * 0.8);
        }

        // Penalty for creating 'dead space' that is too small for any likely item (e.g. < 10)
        if post_residual < 10 {
            score += 15.0;
        }

        // Coupling: penalize bins that deviate significantly from the mean_residual
        // to encourage uniform packing density
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}
